(function () {
    try {
        var q = new URLSearchParams(window.location.search || '');
        if (q.get('cj_probe') === '1') {
            window.CJ_CHUNK_BASE_URL = new URL('fixtures/chunks/', window.location.href).href;
            window.CJ_DNR_CHUNK_COUNT = 1;
        }
        if (q.get('cj_litho_g') === '1') {
            window.CJ_LITHO_G_URL = true;
        }
    } catch (e) {}
})();

let selectedWellForLog = null;
let wells = [];
/* Expose for Playwright / scripts/viewer_probe.py (window.wells.length, DNR-991020, etc.). */
if (typeof window !== 'undefined') {
    try {
        Object.defineProperty(window, 'wells', {
            get: function () { return wells; },
            enumerable: true,
            configurable: true
        });
    } catch (eW) {}
}
function resolveWellForDisplay(id) {
    return wells.find(function(well) { return well.id === id; }) || null;
}
let map = null;
let gpsPosition = null;
let tempMarker = null;
let locationMarker = null;
/** Created in initMap only — avoid ReferenceError if Leaflet CDN fails before this script runs. */
let wellLayer = null;
let currentFilters = { text: '', minDepth: 0, maxDepth: 9999 };
let userElevationM = null;
let lastWellElevationsM = null;
var searchCenter = null;
var RADIUS_MI = 2;
/** Set true first time we start fetching DNR chunks (toggle, locate, ?lat=&lon=, or default auto-load). */
var _dnrFullLoadStarted = false;
function ensureFullDnrDatasetLoaded() {
    if (_dnrFullLoadStarted) return;
    _dnrFullLoadStarted = true;
    loadFullDnrDataset();
}
function showLoadingPanelActive() {
    var panel = document.getElementById('loadingDnrPanel');
    var status = document.getElementById('loadingDnrStatus');
    var strong = panel ? panel.querySelector('strong') : null;
    if (strong) strong.textContent = 'Loading well data in the background…';
    if (status) status.textContent = 'Fetching DNR chunks (map stays light). Use 📍 / address / coordinates to focus wells near your point.';
    if (panel) {
        panel.classList.add('bg-emerald-100', 'border-emerald-300', 'text-emerald-800');
        panel.classList.remove('bg-slate-50', 'border-slate-200', 'text-slate-700');
        panel.style.display = '';
    }
}
function setLoadingPanelDeferred() {
    var panel = document.getElementById('loadingDnrPanel');
    var status = document.getElementById('loadingDnrStatus');
    var strong = panel ? panel.querySelector('strong') : null;
    if (strong) strong.textContent = 'DNR load is deferred';
    if (status) status.textContent = 'Set window.CJ_DEFER_DNR_CHUNK_LOAD = false (or remove it) to load on open. When deferred, use 📍 / address / coordinates to start loading.';
    if (panel) {
        panel.classList.remove('bg-emerald-100', 'border-emerald-300', 'text-emerald-800');
        panel.classList.add('bg-slate-50', 'border-slate-200', 'text-slate-700');
        panel.style.display = '';
    }
}
function maybeAutoStartDnrChunksOnInit() {
    try {
        var u = new URL(window.location.href);
        /* Fixture probe must not run loadFullDnrDataset before PapaParse (CDN) exists — else we keep demo wells and g-label fixtures time out. */
        if (u.searchParams.get('cj_probe') === '1') {
            (function cjProbeWaitPapaThenLoad() {
                if (typeof Papa !== 'undefined') {
                    ensureFullDnrDatasetLoaded();
                    return;
                }
                setTimeout(cjProbeWaitPapaThenLoad, 40);
            })();
            return;
        }
        if (u.searchParams.get('cj_litho_g') === '1' || window.CJ_LITHO_G_URL === true) {
            /* Load data + debug panel only (keeps map light). */
            ensureFullDnrDatasetLoaded();
            return;
        }
        var lat = parseFloat(u.searchParams.get('lat') || '');
        var lon = parseFloat(u.searchParams.get('lon') || '');
        if (!isNaN(lat) && !isNaN(lon)) {
            ensureFullDnrDatasetLoaded();
            return;
        }
    } catch (e) {}
    /* Default: auto-fetch full DNR chunks on load (banner shows progress + chunk URL). Opt out: window.CJ_DEFER_DNR_CHUNK_LOAD = true */
    if (typeof window !== 'undefined' && window.CJ_DEFER_DNR_CHUNK_LOAD === true) {
        setLoadingPanelDeferred();
        return;
    }
    ensureFullDnrDatasetLoaded();
}
/** Wells on map + list: always on unless Hide well labels is enabled. */
function userRequestedWellMarkers() {
    var hideWells = document.getElementById('hideWells') && document.getElementById('hideWells').checked;
    if (hideWells) return false;
    return true;
}
/** Makes combo-marker + depth/g-r tag text bigger/smaller (map +/− is separate Leaflet control). */
var markerLabelScale = 1;
function adjustMarkerLabelScale(delta) {
    markerLabelScale = Math.max(0.55, Math.min(1.85, markerLabelScale + delta));
    if (typeof refreshMap === 'function') refreshMap();
}

