    var mu = m / (a * (1 - e2/4 - 3*e2*e2/64));
    var fp = mu + (3*e1/2 - 27*e1*e1*e1/32) * Math.sin(2*mu) + (21*e1*e1/16 - 55*e1*e1*e1*e1/32) * Math.sin(4*mu) + (151*e1*e1*e1/96) * Math.sin(6*mu);
    var c1 = e2 * Math.cos(fp) * Math.cos(fp) / (1 - e2);
    var t1 = Math.tan(fp) * Math.tan(fp);
    var n1 = a / Math.sqrt(1 - e2 * Math.sin(fp) * Math.sin(fp));
    var r1 = a * (1 - e2) / Math.pow(1 - e2 * Math.sin(fp) * Math.sin(fp), 1.5);
    var d = x / (n1 * k0);
    var lat = fp - (n1 * Math.tan(fp) / r1) * (d*d/2 - (5 + 3*t1 + 10*c1 - 4*c1*c1) * d*d*d*d/24);
