function handleCSV(file) {
    if (!file) return;
    if (typeof Papa === 'undefined') { alert('CSV import needs internet. The 65 built-in wells are already on the map.'); return; }
    Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: function(results) {
            /* Same pipeline as chunk loader so lithology_json + g labels stay consistent. */
            _lithoCache = {};
            wells = (results.data || []).map(normalizeCsvRow).filter(Boolean);
            cjSaveWellsToStorage();
            var totalEl = document.getElementById('totalWells');
            if (totalEl) totalEl.textContent = wells.length.toLocaleString();
            addMarkersInRadius();
            updateWellsList();
            alert('Loaded ' + wells.length + ' wells. Use address, coordinates, or Use My Location to see wells within ' + RADIUS_MI + ' mi.');
        }
    });
}

function clearAllWells() {
    if (confirm('Clear ALL wells and search?')) {
        wells = [];
        _lithoCache = {};
        searchCenter = null;
        _dnrFullLoadStarted = false;
        localStorage.removeItem('cjWells');
        clearMarkers();
        if (tempMarker && map) map.removeLayer(tempMarker);
        tempMarker = null;
        updateWellsList();
    }
}

function exportCSV() {
    if (!wells.length) return alert('No wells to export.');
    if (typeof Papa === 'undefined') { alert('Export needs internet.'); return; }
    const keys = [...new Set(wells.flatMap(w => Object.keys(w)))];
    const csv = Papa.unparse(wells, { columns: keys });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'cj_wells_export_' + new Date().toISOString().slice(0, 10) + '.csv';
    a.click();
    URL.revokeObjectURL(a.href);
}

function getWellsInView() {
    if (!map || !wells.length) return [];
    var bounds = map.getBounds();
    var s = bounds.getSouth(), n = bounds.getNorth();
    var w = bounds.getWest(), e = bounds.getEast();
    return wells.filter(function(well) {
        var lat = Number(well.lat), lon = Number(well.lon);
        return lat >= s && lat <= n && lon >= w && lon <= e;
    });
}

/** If the map shows no wells while data exists, zoom to a sample of loaded wells (demo cluster or chunk extent). */
function cjFitMapToWellsIfNoneVisible() {
    if (typeof L === 'undefined' || !map) return;
    if (!wells || !wells.length) return;
    if (searchCenter) return;
    var hideWells = document.getElementById('hideWells') && document.getElementById('hideWells').checked;
    if (hideWells) return;
    try {
        if (getWellsInView().length > 0) return;
    } catch (e0) { return; }
    try {
        var bounds = L.latLngBounds();
        var cap = 4000;
        var step = Math.max(1, Math.ceil(wells.length / cap));
        for (var i = 0; i < wells.length; i += step) {
            var la = Number(wells[i].lat), lo = Number(wells[i].lon);
            if (!isNaN(la) && !isNaN(lo)) bounds.extend([la, lo]);
        }
        if (bounds.isValid()) {
            map.fitBounds(bounds, { padding: [48, 48], maxZoom: 14, animate: true });
        }
    } catch (e) {}
}

function getWellBottomElev(w) {
    var wbe = w.well_bottom_elev;
    if (wbe != null && wbe !== '' && !isNaN(Number(wbe))) return Number(wbe);
    var ge = w.ground_elev;
