    if (gpm <= 10) return '#1d4ed8';
    if (gpm <= 25) return '#059669';
    if (gpm <= 50) return '#d97706';
    return '#dc2626';
}

/** Band for yield filter; missing/zero pump rate → 'unknown' (always passes when any GPM band is selected). */
function yieldRange(gpm) {
    if (gpm == null || isNaN(Number(gpm)) || Number(gpm) <= 0) return 'unknown';
    if (gpm <= 10) return 'blue';
    if (gpm <= 25) return 'green';
    if (gpm <= 50) return 'orange';
    return 'red';
}

function checkedIds(ids) {
