                    yieldBlue:'blue', yieldGreen:'green', yieldOrange:'orange', yieldRed:'red' };
    var prefix = mode === 'elev' ? 'elev' : 'yield';
    var ids = mode === 'elev'
        ? [prefix+'Blue', prefix+'Green', prefix+'Orange', prefix+'Red']
        : [prefix+'Blue', prefix+'Green', prefix+'Orange', prefix+'Red'];
    return checkedIds(ids).map(function(id) { return rangeMap[id]; });
