function wellTypeColor(w) {
    if (isDryHole(w)) return '#111827';
    if (isBucketWell(w)) return '#f97316';
    if (window.DnrClassifyV3 && typeof window.DnrClassifyV3.wellTypeColor === 'function') {
        return window.DnrClassifyV3.wellTypeColor(w);
    }
    var aq = (w.aquifer || "").toLowerCase();
    var locType = (w.location_type || w.loc_type || "").toLowerCase();
    if (aq.indexOf("estimated") >= 0 || locType.indexOf("estimated") >= 0) return '#16a34a';
    if (isUnconsolidatedWell(w)) return '#2563eb';
    return '#dc2626';
}

function wellTypeLabel(w) {
    // Prefer dual classifier (map-face R/G/S). Yield-missing dry heuristics
    // only when classifier unavailable — they false-flag many real logs.
    if (window.DnrClassifyV3 && typeof window.DnrClassifyV3.wellTypeLabel === 'function') {
        try {
            var dualLb = window.DnrClassifyV3.wellTypeLabel(w);
            if (dualLb) return dualLb;
        } catch (eLb) { /* fall through */ }
    }
    if (isDryHole(w)) return 'Dry';
    if (isBucketWell(w)) return 'Bucket';
    var aq = (w.aquifer || "").toLowerCase();
