/** Face-chip colors on flat combo rows (hub parity 2026-07-22). S = yellow. */
var FACE_CHIP_COLORS = {
    r: '#ffffff',
    g: '#ffffff',
    s: '#fde047',
    sep: 'rgba(255,255,255,0.75)'
};

/**
 * Parse map-face setLabel into ordered visual chip tokens.
 * Single source of truth — no plain text + chips dual.
 */
function parseFaceLabelTokens(label) {
    var raw = String(label == null ? '' : label).trim();
    if (!raw) return [];
    var parts = raw.split(/\s*[·/]\s*/).map(function(s) { return s.trim(); }).filter(Boolean);
    var other = [];
    var rock = [];
    for (var i = 0; i < parts.length; i++) {
        var p = parts[i];
        var r = /^R@?(\d+)$/i.exec(p);
        if (r) { rock.push('r' + r[1]); continue; }
        var gThick = /^G(\d+)\s+(\d+)$/i.exec(p);
        if (gThick) { other.push('g' + gThick[1] + ' ' + gThick[2]); continue; }
        var sThick = /^S(\d+)\s+(\d+)$/i.exec(p);
        if (sThick) { other.push('s' + sThick[1] + ' ' + sThick[2]); continue; }
        var gAt = /^G@(\d+)$/i.exec(p);
        if (gAt) { other.push('g' + gAt[1]); continue; }
        // skip unparsed — never double-render free text
    }
    // Dom 2026-07-23: rock always last (gravel before rock)
    return other.concat(rock);
}

/** Ordered tokens from classifier setLabel only (single-label standard). */
function getOrderedTagTokens(w) {
    try {
        if (window.DnrClassifyV3 && typeof window.DnrClassifyV3.getOrderedTagTokens === 'function') {
            var fromV3 = window.DnrClassifyV3.getOrderedTagTokens(w);
            if (fromV3 && fromV3.length) return fromV3;
        }
        if (window.DnrClassifyV3 && typeof window.DnrClassifyV3.classifyWellDual === 'function') {
            var dual = window.DnrClassifyV3.classifyWellDual(w);
            if (dual.special === 'dry' || dual.special === 'bucket') return [];
            if (dual.setLabel) {
                var fromFace = parseFaceLabelTokens(dual.setLabel);
                if (fromFace.length) return fromFace;
            }
        }
    } catch (eTok) { /* fall through */ }
    var t = wellGrRNumberForTag(w);
    if (t && t.kind === 'r') return ['r' + t.n];
    if (t && t.kind === 'g') return ['g' + t.n];
    return [];
}

function escFace(s) {
    return String(s == null ? '' : s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

/** HTML for R/G/S on flat-color combo row. R+G white, S yellow. */
function formatFaceLabelHtml(label) {
    var tokens = parseFaceLabelTokens(label);
    if (!tokens.length) return null;
    var parts = [];
    for (var i = 0; i < tokens.length; i++) {
        var tok = tokens[i];
        var r = /^r(\d+)$/i.exec(tok);
        if (r) {
            parts.push('<span style="color:' + FACE_CHIP_COLORS.r + ';font-weight:800">R' + escFace(r[1]) + '</span>');
            continue;
        }
        var g = /^g(\d+)\s+(\d+)$/i.exec(tok);
        if (g) {
            parts.push('<span style="color:' + FACE_CHIP_COLORS.g + ';font-weight:800">G' + escFace(g[1]) + ' ' + escFace(g[2]) + '</span>');
            continue;
        }
        var s = /^s(\d+)\s+(\d+)$/i.exec(tok);
        if (s) {
            parts.push('<span style="color:' + FACE_CHIP_COLORS.s + ';font-weight:800">S' + escFace(s[1]) + ' ' + escFace(s[2]) + '</span>');
            continue;
        }
        var gBare = /^g(\d+)$/i.exec(tok);
        if (gBare) {
            parts.push('<span style="color:' + FACE_CHIP_COLORS.g + ';font-weight:800">G' + escFace(gBare[1]) + '</span>');
            continue;
        }
    }
    if (!parts.length) return null;
    return parts.join('<span style="color:' + FACE_CHIP_COLORS.sep + ';font-weight:700"> / </span>');
}

/**
 * List chips (hub NearestWellsStrip parity): R red, G blue, S yellow.
 * Single series from face tokens only — no plain typeLb + chips dual.
 */
function formatListChipHtml(tokens) {
    if (!tokens || !tokens.length) return '';
    return tokens.map(function(tok) {
        var mr = /^r(\d+)$/i.exec(tok);
        if (mr) {
            return '<span class="inline-flex items-end mr-2" title="Rock top ' + escFace(mr[1]) + ' ft">' +
                '<span style="font-size:10px;font-weight:700;color:#dc2626">R</span>' +
                '<span style="font-size:15px;font-weight:800;line-height:1;color:#b91c1c">' + escFace(mr[1]) + '</span></span>';
        }
        var mg = /^g(\d+)\s+(\d+)$/i.exec(tok);
        if (mg) {
            return '<span class="inline-flex items-end mr-2" title="Aquifer G' + escFace(mg[1]) + ' · ' + escFace(mg[2]) + ' ft thick">' +
                '<span style="font-size:10px;font-weight:700;color:#2563eb">G' + escFace(mg[1]) + '</span>' +
                '<span style="font-size:15px;font-weight:800;line-height:1;color:#1d4ed8">&nbsp;' + escFace(mg[2]) + '</span></span>';
        }
        var ms = /^s(\d+)\s+(\d+)$/i.exec(tok);
        if (ms) {
