    }
    if (effRows === 2) {
        return { maxW: Math.min(238, Math.round(156 * z)), maxH: Math.round(64 * z) };
    }
    return { maxW: Math.min(224, Math.round(145 * z)), maxH: Math.round(82 * z) };
