    var rowH = Math.max(Math.ceil(comboFs * 1.48), Math.round(13 * zScale));
    var innerH = Math.max(Math.ceil(comboFs * 1.22), er * rowH + (er > 1 ? er - 1 : 0));
    return { innerW: innerW, innerH: innerH, rowH: rowH };
}

