    var lt = Math.max(longestText, 3);
    var er = Math.max(1, effRows);
    var bounds = cjComboChipMaxBounds(er, zScale);
    var maxW = bounds.maxW;
    var maxH = bounds.maxH;
    var mls = Math.max(0.75, Math.min(1.45, markerLabelScale));
    var lo = 4.5 * mls;
    var hi = (er <= 1 ? 16.5 : (er === 2 ? 12.8 : 10.5)) * mls;
    if (hi > 17) hi = 17;
    var best = lo;
    for (var it = 0; it < 22; it++) {
        var mid = (lo + hi) / 2;
        var m = cjComboMarkerMeasure(mid, lt, er, zScale);
        if (m.innerW <= maxW && m.innerH <= maxH) {
            best = mid;
            lo = mid;
        } else {
            hi = mid;
        }
    }
    var fs = Math.max(4.5, Math.round(best * 10) / 10);
    var meas = cjComboMarkerMeasure(fs, lt, er, zScale);
    for (var fix = 0; fix < 6; fix++) {
        if (meas.innerW <= maxW && meas.innerH <= maxH) break;
        fs = Math.max(4.5, Math.round((fs * 0.9) * 10) / 10);
        meas = cjComboMarkerMeasure(fs, lt, er, zScale);
    }
    return fs;
}

function refreshMap() {
    var mode = getActiveMode();
    var showElev = hasElevToggles();
    var showYield = hasYieldToggles();
    var showType = hasTypeToggles();
    elevationViewActive = showElev;
    yieldViewActive = showYield;

    if (!map || !wellLayer) return;
    wellLayer.clearLayers();
    if (tempMarker && map) { map.removeLayer(tempMarker); tempMarker = null; }

    var hideWells = document.getElementById('hideWells') && document.getElementById('hideWells').checked;
    if (hideWells) {
        updateWellsList();
        return;
    }

    if (!userRequestedWellMarkers()) {
        updateWellsList();
        return;
    }

    var pool = searchCenter ? getWellsWithin2Miles(searchCenter) : getWellsInView();

    var elevRanges = showElev ? getElevRanges() : [];
    var yldRanges = showYield ? getYieldRanges() : [];
    /* Cap dense views; prefer wells that already resolved g/r so tags stay visible. */
    var maxMarkers = 800;
    var filtered = [];
    for (var i = 0; i < pool.length; i++) {
        var w = pool[i];
        if (!passesTypeFilter(w)) continue;
        var dM = getWellDisplayDepthFt(w);
        var d = dM != null ? dM : NaN;
        if (!isNaN(d) && (d < currentFilters.minDepth || d > currentFilters.maxDepth)) continue;
        if (!passesElevFilter(w, elevRanges)) continue;
        if (!passesYieldFilter(w, yldRanges)) continue;
        filtered.push(w);
    }

    if (filtered.length > maxMarkers) {
        filtered.sort(function(a, b) {
            var ha = wellGrRNumberForTag(a) ? 1 : 0;
            var hb = wellGrRNumberForTag(b) ? 1 : 0;
            if (ha !== hb) return hb - ha;
            return 0.5 - Math.random();
        });
        filtered = filtered.slice(0, maxMarkers);
    }

    var rowCount = (showType ? 1 : 0) + (showElev ? 1 : 0) + (showYield ? 1 : 0);
    var zoom = map.getZoom();
    var zScale = Math.max(0.45, Math.min(1.45, 0.32 + (zoom - 7) * 0.09)) * markerLabelScale;
    var dotSize = Math.max(10, Math.round(16 * zScale));

    filtered.forEach(function(w) {
        var latNum = Number(w.lat), lonNum = Number(w.lon);
        var popupLines = ["<b>" + w.id + "</b>"];
        if (w.county) popupLines.push(w.county + " County");
        var depthVal = getWellDisplayDepthFt(w);
        var depthStr = depthVal != null ? Math.round(depthVal).toString() + "'" : '–';
        var depthFtPlain = depthVal != null ? String(Math.round(depthVal)) : '–';
        var extraTag = wellMapGrTag(w);

        if (rowCount >= 1 && mode) {
            var rows = [];
            var gROnCombo = false;
            // Estimated green boxes: subtle type-colored outline (blue gravel / red rock).
            var estRingCls = '';
            var estBorder = null;
            try {
                if (window.DnrClassifyV3) {
                    if (typeof window.DnrClassifyV3.estimatedTypeRingClass === 'function') {
                        estRingCls = window.DnrClassifyV3.estimatedTypeRingClass(w) || '';
                    }
                    if (typeof window.DnrClassifyV3.estimatedTypeBorderColor === 'function') {
                        estBorder = window.DnrClassifyV3.estimatedTypeBorderColor(w);
                    }
                }
            } catch (eEst) { /* ignore */ }
            if (showType) {
                var tc = wellTypeColor(w);
                var tl = wellTypeLabel(w);
                // Flat fill = marker color (blue gravel / red rock / green estimated).
                // Face text = R/G white + S yellow (hub 2026-07-22 flat chips).
                // Never stack depth+grn AND face label (double-label bug).
                var faceHtml = formatFaceLabelHtml(tl);
                if (faceHtml) {
                    rows.push('<div class="cm-row" style="background:' + tc + ';color:#fff">' + faceHtml +
                        '<span style="color:#fff;font-weight:700"> ' + escFace(depthStr) + '</span></div>');
                    gROnCombo = true;
                } else {
                    var typeRowInner = tl + ' ' + depthStr;
                    rows.push('<div class="cm-row" style="background:' + tc + ';color:#fff">' + escFace(typeRowInner) + '</div>');
                }
                // Layer stack only in popup detail — not on map face
                var stackNote = '';
                var locNote = '';
                try {
                    if (window.DnrClassifyV3 && typeof window.DnrClassifyV3.classifyWellDual === 'function') {
                        var dualP = window.DnrClassifyV3.classifyWellDual(w);
                        if (dualP.layerStackLabel && dualP.layerStackLabel !== tl &&
                            String(tl).indexOf(dualP.layerStackLabel) < 0) {
                            stackNote = ' · stack ' + dualP.layerStackLabel;
                        }
                        if (dualP.locationQuality === 'estimated') {
                            locNote = dualP.formationClass === 'rock'
                                ? ' · estimated location · rock'
                                : dualP.formationClass === 'unconsolidated'
                                    ? ' · estimated location · gravel/uncon'
                                    : ' · estimated location';
                        }
                    }
                } catch (ePop) { /* ignore */ }
                popupLines.push(escFace(tl + ' · ' + depthStr + locNote + stackNote));
            }
            if (showElev) {
                var be = getWellBottomElev(w);
                var beLabel = be != null ? be + "'" : '–';
                var eSuf = (!gROnCombo && extraTag) ? extraTag : '';
                if (eSuf) gROnCombo = true;
                rows.push('<div class="cm-row" style="background:' + elevColor(be) + ';color:#fff">' + escFace(beLabel + ' ASL' + eSuf) + '</div>');
                popupLines.push(escFace('Bottom: ' + (be != null ? be + ' ft ASL' : 'unknown') + (eSuf ? ' · ' + eSuf.trim() : '')));
            }
            if (showYield) {
                var gpm = getWellPumpRate(w);
                var gpmLabel = gpm != null ? gpm + ' gpm' : '–';
                var ySuf = (!gROnCombo && extraTag) ? extraTag : '';
                if (ySuf) gROnCombo = true;
                rows.push('<div class="cm-row" style="background:' + yieldColor(gpm) + ';color:#fff">' + escFace(gpmLabel + ySuf) + '</div>');
                popupLines.push(escFace('Yield: ' + (gpm != null ? gpm + ' GPM' : 'unknown') + (ySuf ? ' · ' + ySuf.trim() : '')));
            }
            if (!gROnCombo && extraTag) {
                rows.push('<div class="cm-row" style="background:#475569;color:#fff">' + escFace(extraTag.trim()) + '</div>');
                popupLines.push(escFace(extraTag.trim()));
                gROnCombo = true;
            }
            if (!showType && depthVal != null) popupLines.push(escFace('Depth: ' + depthVal + ' ft'));
            var effRows = rows.length || rowCount;
            var longestText = 0;
            for (var ri = 0; ri < rows.length; ri++) {
                var stripped = rows[ri].replace(/<[^>]+>/g, '');
                if (stripped.length > longestText) longestText = stripped.length;
            }
            var comboFs = cjFitComboMarkerFs(longestText, effRows, zScale);
            var lay = cjComboMarkerMeasure(comboFs, longestText, effRows, zScale);
            var innerW = lay.innerW;
            var innerH = lay.innerH;
            var padB = 4;
            var iconW = innerW + padB * 2;
            var iconH = innerH + padB * 2;
            var estClassAttr = estRingCls ? ('combo-marker ' + estRingCls) : 'combo-marker';
            var estBorderStyle = estBorder
                ? ('border:1px solid ' + estBorder + ';box-shadow:0 1px 2px rgba(0,0,0,0.35);')
                : '';
            var markerHtml = '<div class="' + estClassAttr + '" data-est-type="' + (estRingCls || 'none') + '" data-est-border="' + (estBorder || 'none') + '" style="font-size:' + comboFs + 'px;width:' + innerW + 'px;min-width:' + innerW + 'px;max-width:' + innerW + 'px;' + estBorderStyle + '">' + rows.join('') + '</div>';
            var marker = L.marker([latNum, lonNum], {
                icon: L.divIcon({ className: 'well-dot', html: markerHtml, iconSize: [iconW, iconH], iconAnchor: [Math.round(iconW / 2), Math.round(iconH / 2)] })
            }).bindPopup(popupLines.join('<br>'));
        } else {
            var color = wellTypeColor(w);
            var estRingDot = '';
            var estBorderDot = null;
            try {
                if (window.DnrClassifyV3) {
                    if (typeof window.DnrClassifyV3.estimatedTypeRingClass === 'function') {
                        estRingDot = window.DnrClassifyV3.estimatedTypeRingClass(w) || '';
                    }
                    if (typeof window.DnrClassifyV3.estimatedTypeBorderColor === 'function') {
                        estBorderDot = window.DnrClassifyV3.estimatedTypeBorderColor(w);
                    }
                }
            } catch (eDot) { /* ignore */ }
            popupLines.push(escFace((depthVal != null ? depthVal : '—') + ' ft' + (extraTag ? ' · ' + extraTag.trim() : '')));
            popupLines.push("<a href='https://maps.apple.com/?daddr=" + latNum + "," + lonNum + "' target='_blank'>Apple Maps</a> · <a href='https://www.google.com/maps/dir/?api=1&destination=" + latNum + "," + lonNum + "' target='_blank'>Google Maps</a>");
            var depthTxt = depthVal != null ? Math.round(depthVal).toString() : '–';
            var tagFs = Math.max(5, Math.round(7 * zScale));
            // Under-dot: face R/G/S plain text (no dual grn residual when face exists)
            var facePlain = wellTypeLabel(w);
            var faceIsChip = facePlain && facePlain !== 'Well' && facePlain !== 'Dry' && facePlain !== 'Bucket' &&
                parseFaceLabelTokens(facePlain).length > 0;
            var underDotText = faceIsChip ? facePlain : (extraTag ? String(extraTag).trim() : '');
            var tagHtml = underDotText
                ? '<div style="margin-top:1px;font-size:' + tagFs + 'px;font-weight:800;color:#0f172a;text-shadow:0 0 3px #fff,0 0 4px #fff;line-height:1.1;white-space:nowrap">' + escFace(underDotText) + '</div>'
                : '';
            var tagLen = underDotText ? underDotText.length : 0;
            var dotClass = estRingDot ? ('well-marker ' + estRingDot) : 'well-marker';
            var dotBorderStyle = estBorderDot
                ? ('border:1px solid ' + estBorderDot + ';box-shadow:0 1px 2px rgba(0,0,0,0.35);')
                : 'border:2px solid #fff;';
            var dotBlock = '<div style="display:flex;flex-direction:column;align-items:center;">' +
                '<div class="' + dotClass + '" data-est-type="' + (estRingDot || 'none') + '" data-est-border="' + (estBorderDot || 'none') + '" style="background:' + color + ';width:' + dotSize + 'px;height:' + dotSize + 'px;flex-shrink:0;' + dotBorderStyle + '"><span class="well-depth-label" style="font-size:' + Math.max(6, Math.round(9 * zScale)) + 'px">' + escFace(depthTxt) + '</span></div>' +
                tagHtml +
                '</div>';
            var bw = tagHtml ? Math.max(dotSize, Math.min(130, Math.round(6 + tagLen * tagFs * 0.52))) : dotSize;
            var bh = tagHtml ? dotSize + Math.round(tagFs + 8) : dotSize;
            var marker = L.marker([latNum, lonNum], {
                icon: L.divIcon({ className: 'well-dot',
                    html: dotBlock,
                    iconSize: [bw, bh], iconAnchor: [Math.round(bw / 2), Math.round(dotSize / 2)] })
            }).bindPopup(popupLines.join('<br>'));
        }
        marker.on('click', function() { showDetailById(w.id); });
        wellLayer.addLayer(marker);
    });

    updateWellsList();
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMap);
} else {
    initMap();
}
